/* नेपालीमा हाङ्गुल — service worker
 * Generated by build_bilingual.py. Edit the template there, not here.
 * Strategy:
 *   navigation      -> network-first (4.5s), cache fallback, then offline page
 *   audio/ images/ icons/ fonts -> stale-while-revalidate
 *   /api/tts        -> never intercepted (per-request audio, app falls back to Web Speech)
 */
const VERSION = "v30";
const CACHE = "nepalihangul-" + VERSION;

const QUIZ_IMAGES = ["images/quiz/bag.webp", "images/quiz/bank.webp", "images/quiz/blackboard.webp", "images/quiz/box.webp", "images/quiz/bus.webp", "images/quiz/cafe.webp", "images/quiz/chair.webp", "images/quiz/cinema.webp", "images/quiz/classroom.webp", "images/quiz/clock.webp", "images/quiz/computer.webp", "images/quiz/desk.webp", "images/quiz/factory.webp", "images/quiz/hat.webp", "images/quiz/helmet.webp", "images/quiz/hospital.webp", "images/quiz/machine.webp", "images/quiz/medicine.webp", "images/quiz/money.webp", "images/quiz/pencil.webp", "images/quiz/phone.webp", "images/quiz/photo.webp", "images/quiz/restaurant.webp", "images/quiz/rice.webp", "images/quiz/truck.webp", "images/quiz/water.webp"];

/* Letter pronunciation clips: one per jamo, generated from the neural voice. */
const PRON_CLIPS = ["audio/pron/a.mp3", "audio/pron/ae.mp3", "audio/pron/b.mp3", "audio/pron/ch.mp3", "audio/pron/d.mp3", "audio/pron/e.mp3", "audio/pron/eo.mp3", "audio/pron/eu.mp3", "audio/pron/g.mp3", "audio/pron/h.mp3", "audio/pron/i.mp3", "audio/pron/j.mp3", "audio/pron/jj.mp3", "audio/pron/k.mp3", "audio/pron/kk.mp3", "audio/pron/m.mp3", "audio/pron/n.mp3", "audio/pron/ng.mp3", "audio/pron/o.mp3", "audio/pron/oe.mp3", "audio/pron/p.mp3", "audio/pron/pp.mp3", "audio/pron/r.mp3", "audio/pron/s.mp3", "audio/pron/ss.mp3", "audio/pron/t.mp3", "audio/pron/tt.mp3", "audio/pron/u.mp3", "audio/pron/ui.mp3", "audio/pron/wa.mp3", "audio/pron/wae.mp3", "audio/pron/we.mp3", "audio/pron/wi.mp3", "audio/pron/wo.mp3", "audio/pron/ya.mp3", "audio/pron/yae.mp3", "audio/pron/ye.mp3", "audio/pron/yeo.mp3", "audio/pron/yo.mp3", "audio/pron/yu.mp3"];

const SHELL = [
  "./",
  "./index.html",
  "./manifest.webmanifest",
  "./icons/favicon.ico",
  "./icons/favicon-32.png",
  "./icons/icon-192.png",
  "./icons/icon-512.png",
  "./icons/icon-maskable-192.png",
  "./icons/icon-maskable-512.png",
  "./icons/apple-touch-icon.png",
  "./audio/sfx/correct.mp3",
  "./audio/sfx/wrong.mp3",
  "./audio/sfx/complete.mp3",
  "./audio/sfx/streak.mp3",
  "./audio/sfx/correct_soft.mp3",
  "./audio/sfx/wrong_soft.mp3",
  "./audio/sfx/tick.mp3",
  "./audio/sfx/start.mp3"
].concat(PRON_CLIPS).concat(QUIZ_IMAGES);

const OFFLINE_HTML = [
  "<!DOCTYPE html><html lang='ne'><head><meta charset='utf-8'>",
  "<meta name='viewport' content='width=device-width,initial-scale=1'>",
  "<title>अफलाइन — नेपालीमा हाङ्गुल</title>",
  "<style>",
  "html,body{margin:0;height:100%}",
  "body{display:grid;place-items:center;background:#faf5ec;color:#2b2520;",
  "font-family:Mukta,system-ui,sans-serif;text-align:center;padding:24px}",
  ".card{max-width:340px}",
  ".mark{display:grid;place-items:center;width:64px;height:64px;margin:0 auto 18px;",
  "border-radius:50%;background:#fff;border:1.5px solid #e8ddca;font-size:30px}",
  "h1{font-size:22px;margin:0 0 8px;letter-spacing:-.2px}",
  "p{margin:0 0 20px;color:#6f6557;line-height:1.6;font-size:14.5px}",
  "button{font:inherit;font-weight:700;padding:12px 22px;border-radius:999px;border:0;",
  "background:#ad4665;color:#fff;cursor:pointer}",
  "</style></head><body><div class='card'>",
  "<div class='mark'>한</div>",
  "<h1>अफलाइन छ</h1>",
  "<p>यो पटक पूरा साइट क्यास भएको छैन। इन्टरनेट जोडेर फेरि खोल्नुहोस् — एक पटक खुलेपछि पाठ, क्विज र शब्दार्थ अफलाइन पनि चल्छ।</p>",
  "<button onclick='location.reload()'>फेरि प्रयास गर्नुहोस्</button>",
  "</div></body></html>"
].join("");

self.addEventListener("install", function (event) {
  event.waitUntil((async function () {
    const cache = await caches.open(CACHE);
    await Promise.all(SHELL.map(async function (url) {
      try {
        await cache.add(new Request(url, { cache: "reload" }));
      } catch (err) {
        /* a missing icon or image must not abort the whole install */
      }
    }));
    await self.skipWaiting();
  })());
});

self.addEventListener("activate", function (event) {
  event.waitUntil((async function () {
    const keys = await caches.keys();
    await Promise.all(keys.filter(function (k) {
      return k.indexOf("nepalihangul-") === 0 && k !== CACHE;
    }).map(function (k) { return caches.delete(k); }));
    if (self.registration.navigationPreload) {
      try { await self.registration.navigationPreload.disable(); } catch (e) {}
    }
    await self.clients.claim();
  })());
});

function withTimeout(promise, ms) {
  return new Promise(function (resolve, reject) {
    const t = setTimeout(function () { reject(new Error("timeout")); }, ms);
    promise.then(
      function (v) { clearTimeout(t); resolve(v); },
      function (e) { clearTimeout(t); reject(e); }
    );
  });
}

async function networkFirst(request) {
  const cache = await caches.open(CACHE);
  try {
    const fresh = await withTimeout(fetch(request), 4500);
    if (fresh && fresh.ok) cache.put("./index.html", fresh.clone());
    return fresh;
  } catch (err) {
    const hit = (await cache.match(request, { ignoreSearch: true })) ||
                (await cache.match("./index.html"));
    if (hit) return hit;
    return new Response(OFFLINE_HTML, {
      status: 200,
      headers: { "Content-Type": "text/html; charset=utf-8" }
    });
  }
}

async function staleWhileRevalidate(request, event) {
  const cache = await caches.open(CACHE);
  const hit = await cache.match(request);
  const refresh = fetch(request).then(function (resp) {
    if (resp && (resp.ok || resp.type === "opaque") && resp.status !== 206) {
      cache.put(request, resp.clone());
    }
    return resp;
  }).catch(function () { return null; });

  if (hit) {
    event.waitUntil(refresh);
    return hit;
  }
  const fresh = await refresh;
  return fresh || Response.error();
}

self.addEventListener("fetch", function (event) {
  const request = event.request;
  if (request.method !== "GET") return;

  const url = new URL(request.url);

  // Per-request TTS audio is generated fresh every call — caching it is pointless
  if (url.pathname.indexOf("/api/tts") !== -1) return;

  if (request.mode === "navigate") {
    event.respondWith(networkFirst(request));
    return;
  }

  const sameOrigin = url.origin === self.location.origin;
  const isStatic = sameOrigin && /^\/(audio|images|icons)\//.test(url.pathname);
  const isFont = /fonts\.googleapis\.com$|fonts\.gstatic\.com$/.test(url.hostname);

  if (isStatic || isFont) {
    event.respondWith(staleWhileRevalidate(request, event));
    return;
  }

  // sw.js and the manifest should always come from the network when possible
  if (sameOrigin && /^\/(sw\.js|manifest\.webmanifest)$/.test(url.pathname)) return;

  event.respondWith(
    fetch(request).catch(function () {
      return caches.match(request).then(function (hit) {
        return hit || Response.error();
      });
    })
  );
});

self.addEventListener("message", function (event) {
  if (event.data === "skip-waiting") self.skipWaiting();
});
